from datetime import datetime

class Solution(db.Model):
    __tablename__ = 'solutions'

    id = db.Column(db.Integer, primary_key=True)
    code = db.Column(db.Text, nullable=False)
    language = db.Column(db.String(50), nullable=False)
    status = db.Column(db.String(20), nullable=False, default="Pending")  # Possible values: Pending, Accepted, Rejected
    created_at = db.Column(db.DateTime, nullable=False, default=datetime.utcnow)
    updated_at = db.Column(db.DateTime, nullable=True, onupdate=datetime.utcnow)

    # Foreign keys
    user_id = db.Column(db.Integer, db.ForeignKey('users.id'), nullable=False)
    problem_id = db.Column(db.Integer, db.ForeignKey('problems.id'), nullable=False)

    # Relationships
    user = db.relationship('User', backref=db.backref('solutions', lazy=True))
    problem = db.relationship('Problem', backref=db.backref('solutions', lazy=True))

    def __repr__(self):
        return f'<Solution {self.id} - User {self.user_id} - Problem {self.problem_id}>'

    def save(self):
        """Save the current solution instance to the database."""
        db.session.add(self)
        db.session.commit()

    @classmethod
    def get_by_id(cls, solution_id):
        """Retrieve a solution by its ID."""
        return cls.query.get(solution_id)

    @classmethod
    def get_all_solutions(cls):
        """Retrieve all solutions."""
        return cls.query.all()

    @classmethod
    def get_by_user_and_problem(cls, user_id, problem_id):
        """Retrieve solutions submitted by a specific user for a specific problem."""
        return cls.query.filter_by(user_id=user_id, problem_id=problem_id).all()

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.models.problem import Problem
from app.database import db

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def list_problems():
    try:
        problems = Problem.query.all()
        return render_template('templates/problem.html', problems=problems)
    except Exception as e:
        flash(f"An error occurred while fetching problems: {str(e)}", 'danger')
        return redirect(url_for('index'))

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def view_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            flash('Problem not found.', 'warning')
            return redirect(url_for('problem.list_problems'))
        return render_template('templates/problem.html', problem=problem)
    except Exception as e:
        flash(f"An error occurred while fetching the problem: {str(e)}", 'danger')
        return redirect(url_for('problem.list_problems'))

@problem_bp.route('/problems/create', methods=['GET', 'POST'])
def create_problem():
    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        difficulty = request.form.get('difficulty')

        if not title or not description or not difficulty:
            flash('All fields are required.', 'warning')
            return redirect(url_for('problem.create_problem'))

        try:
            new_problem = Problem(title=title, description=description, difficulty=difficulty)
            db.session.add(new_problem)
            db.session.commit()
            flash('Problem created successfully!', 'success')
            return redirect(url_for('problem.list_problems'))
        except Exception as e:
            db.session.rollback()
            flash(f"An error occurred while creating the problem: {str(e)}", 'danger')

    return render_template('templates/submit.html')

@problem_bp.route('/problems/<int:problem_id>/edit', methods=['GET', 'POST'])
def edit_problem(problem_id):
    problem = Problem.query.get(problem_id)
    if not problem:
        flash('Problem not found.', 'warning')
        return redirect(url_for('problem.list_problems'))

    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        difficulty = request.form.get('difficulty')

        if not title or not description or not difficulty:
            flash('All fields are required.', 'warning')
            return redirect(url_for('problem.edit_problem', problem_id=problem_id))

        try:
            problem.title = title
            problem.description = description
            problem.difficulty = difficulty
            db.session.commit()
            flash('Problem updated successfully!', 'success')
            return redirect(url_for('problem.list_problems'))
        except Exception as e:
            db.session.rollback()
            flash(f"An error occurred while updating the problem: {str(e)}", 'danger')

    return render_template('templates/submit.html', problem=problem)

@problem_bp.route('/problems/<int:problem_id>/delete', methods=['POST'])
def delete_problem(problem_id):
    problem = Problem.query.get(problem_id)
    if not problem:
        flash('Problem not found.', 'warning')
        return redirect(url_for('problem.list_problems'))

    try:
        db.session.delete(problem)
        db.session.commit()
        flash('Problem deleted successfully!', 'success')
    except Exception as e:
        db.session.rollback()
        flash(f"An error occurred while deleting the problem: {str(e)}", 'danger')

    return redirect(url_for('problem.list_problems'))

from flask import Blueprint, request, jsonify, render_template
from app.models.user import User
from app.database import db

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def list_users():
    """
    List all users
    """
    try:
        users = User.get_all_users()
        return jsonify([user.to_dict() for user in users]), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """
    Get a user by ID
    """
    try:
        user = User.get_by_id(user_id)
        if user:
            return jsonify(user.to_dict()), 200
        else:
            return jsonify({'error': 'User not found'}), 404
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/create', methods=['POST'])
def create_user():
    """
    Create a new user
    """
    try:
        data = request.json
        if not data or not data.get('username') or not data.get('email'):
            return jsonify({'error': 'Invalid input'}), 400

        new_user = User(username=data['username'], email=data['email'])
        db.session.add(new_user)
        db.session.commit()
        return jsonify(new_user.to_dict()), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>/edit', methods=['PUT'])
def edit_user(user_id):
    """
    Edit user details
    """
    try:
        data = request.json
        user = User.get_by_id(user_id)

        if not user:
            return jsonify({'error': 'User not found'}), 404

        if 'username' in data:
            user.username = data['username']
        if 'email' in data:
            user.email = data['email']

        db.session.add(user)
        db.session.commit()
        return jsonify(user.to_dict()), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>/delete', methods=['DELETE'])
def delete_user(user_id):
    """
    Delete a user
    """
    try:
        user = User.get_by_id(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        db.session.delete(user)
        db.session.commit()
        return jsonify({'message': 'User deleted successfully'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

